def get_city_for_coords(lat, lon):
    """Determine which city a coordinate belongs to."""
    for city_key, city_info in CITIES.items():
        if abs(lat - city_info['lat']) < 0.1 and abs(lon - city_info['lon']) < 0.1:
            return city_key
    return None


def preprocess_cities():
    """Generate city-specific GeoJSON files."""
    # Load all features
    with open(PROCESSED_DIR / 'all_hospitals.geojson') as f:
        all_hospitals = json.load(f)
    with open(PROCESSED_DIR / 'all_schools.geojson') as f:
        all_schools = json.load(f)
    with open(PROCESSED_DIR / 'water.geojson') as f:
        all_water = json.load(f)
    with open(PROCESSED_DIR / 'building_centroids.geojson') as f:
        all_buildings = json.load(f)
    
    print('Processing cities...')
    
    for city_key, city_info in CITIES.items():
        # Filter features for this city
        hospitals = []
        for feat in all_hospitals['features']:
            lat = feat['properties'].get('lat', 0)
            lon = feat['properties'].get('lon', 0)
            if get_city_for_coords(lat, lon) == city_key:
                hospitals.append(feat)
        
        schools = []
        for feat in all_schools['features']:
            lat = feat['properties'].get('lat', 0)
            lon = feat['properties'].get('lon', 0)
            if get_city_for_coords(lat, lon) == city_key:
                schools.append(feat)
        
        water = []
        for feat in all_water['features']:
            lat = feat['properties'].get('lat', 0)
            lon = feat['properties'].get('lon', 0)
            if get_city_for_coords(lat, lon) == city_key:
                water.append(feat)
        
        buildings = []
        for feat in all_buildings['features']:
            lat = feat['properties'].get('lat', 0)
            lon = feat['properties'].get('lon', 0)
            if get_city_for_coords(lat, lon) == city_key:
                buildings.append(feat)
        
        # Save city-specific files
        city_dir = PROCESSED_DIR / city_key
        city_dir.mkdir(exist_ok=True)
        
        for filename, data in [
            ('hospitals.geojson', hospitals),
            ('schools.geojson', schools),
            ('water.geojson', water),
            ('buildings.geojson', buildings),
        ]:
            with open(city_dir / filename, 'w') as f:
                json.dump({'type': 'FeatureCollection', 'features': data}, f)
        
        # Save city metadata
        with open(city_dir / 'metadata.json', 'w') as f:
            json.dump({
                **city_info,
                'hospital_count': len(hospitals),
                'school_count': len(schools),
                'water_count': len(water),
                'building_count': len(buildings),
            }, f, indent=2)
        
        print(f'  {city_info["name"]}: {len(hospitals)} hospitals, {len(schools)} schools, {len(water)} water')
    
    print('Done!')


if __name__ == '__main__':
    preprocess_cities()
